/*
 * sfun_grid_forming_control: Level-2 C MEX S-function generated by motulator_plecs
 * from the C-Script code of the PLECS model. The C-Script macros are
 * defined with the Simulink API. The state of the code is in static
 * variables, so a model can contain one instance of the block.
 *
 * Build with a C99 compiler with complex.h (gcc, clang, or MinGW-w64):
 *     mex -I<motulator_plecs/c> sfun_grid_forming_control.c
 */

#define S_FUNCTION_NAME sfun_grid_forming_control
#define S_FUNCTION_LEVEL 2

#include "simstruc.h"

#define InputSignal(i, j) (ssGetInputPortRealSignal(S, (i))[j])
#define OutputSignal(i, j) (ssGetOutputPortRealSignal(S, (i))[j])
#define ParamRealData(i, j) (mxGetPr(ssGetSFcnParam(S, (i)))[j])
#define ParamDim(i, d)                                                           \
    ((int)((d) == 0 ? mxGetM(ssGetSFcnParam(S, (i)))                             \
                    : mxGetN(ssGetSFcnParam(S, (i)))))
#define SetErrorMessage(msg) ssSetErrorStatus(S, (msg))
#define ContState(i) (ssGetContStates(S)[i])
#define ContDeriv(i) (ssGetdX(S)[i])

/* Declarations of the C-Script (after simstruc.h, since complex.h
 * defines the macro I) */
/* Generated by motulator_plecs.grid. The control algorithms are in the
 * included C files. The parameters come from the mask of the subsystem. */
#include "common.c"
#include "gfm_observer.c"

#define P(i, j) ParamRealData(i, j)
#define PDIM(i) (ParamDim(i, 0) * ParamDim(i, 1))

/* Parameter value, or NAN for an empty parameter (None in motulator) */
#define PARAM(i) (PDIM(i) > 0 ? P(i, 0) : NAN)

static GFMControlSystem ctrl;

/* Ports and parameters of the C-Script */
static const int INPUT_WIDTHS[] = {1, 1, 3, 1};
static const int FEEDTHROUGH[] = {1, 1, 1, 1};
static const int OUTPUT_WIDTHS[] = {3, 3, 2, 4, 1};
#define NUM_INPUTS 4
#define NUM_OUTPUTS 5
#define NUM_PARAMS 12

static void mdlInitializeSizes(SimStruct *S)
{
    ssSetNumSFcnParams(S, NUM_PARAMS);
    ssSetNumContStates(S, 0);
    ssSetNumDiscStates(S, 0);
    if (!ssSetNumInputPorts(S, NUM_INPUTS)) {
        return;
    }
    for (int k = 0; k < NUM_INPUTS; k++) {
        ssSetInputPortWidth(S, k, INPUT_WIDTHS[k]);
        ssSetInputPortDirectFeedThrough(S, k, FEEDTHROUGH[k]);
        ssSetInputPortRequiredContiguous(S, k, 1);
    }
    if (!ssSetNumOutputPorts(S, NUM_OUTPUTS)) {
        return;
    }
    for (int k = 0; k < NUM_OUTPUTS; k++) {
        ssSetOutputPortWidth(S, k, OUTPUT_WIDTHS[k]);
    }
    ssSetNumSampleTimes(S, 1);
    ssSetOptions(S, SS_OPTION_EXCEPTION_FREE_CODE);
#if defined(MATLAB_MEX_FILE)
    if (ssGetNumSFcnParams(S) != ssGetSFcnParamsCount(S)) {
        return; /* Reported by Simulink */
    }
    for (int k = 0; k < NUM_PARAMS; k++) {
        const mxArray *p = ssGetSFcnParam(S, k);
        if (!mxIsDouble(p) || mxIsComplex(p)) {
            SetErrorMessage(
                "The parameters must be real double arrays.");
            return;
        }
        ssSetSFcnParamTunable(S, k, SS_PRM_NOT_TUNABLE);
    }
    if (ParamDim(9, 0) * ParamDim(9, 1) != 1
        || !(ParamRealData(9, 0) > 0.0)) {
        SetErrorMessage("The sampling period must be a positive scalar.");
        return;
    }
#endif
}

static void mdlInitializeSampleTimes(SimStruct *S)
{
    ssSetSampleTime(S, 0, ParamRealData(9, 0));
    ssSetOffsetTime(S, 0, 0.0);
}

#define MDL_START
static void mdlStart(SimStruct *S)
{
    /* Check the parameters of the mask */
    if (PDIM(0) != 1) {
        SetErrorMessage("i_max must be a scalar.");
        return;
    }
    if (PDIM(1) != 1) {
        SetErrorMessage("L must be a scalar.");
        return;
    }
    if (PDIM(9) != 1) {
        SetErrorMessage("T_s must be a scalar.");
        return;
    }

    /* Configuration (ObserverBasedGridFormingControllerCfg), the defaults are
     * used for empty parameters */
    GFMControllerCfg cfg = gfm_controller_cfg(P(0, 0), P(1, 0));
    if (PDIM(2) > 0) {
        cfg.R = P(2, 0);
    }
    if (PDIM(3) > 0) {
        cfg.R_a = P(3, 0);
    }
    if (PDIM(4) > 0) {
        cfg.k_v = P(4, 0);
    }
    if (PDIM(5) > 0) {
        cfg.alpha_o = P(5, 0);
    }
    if (PDIM(6) > 0) {
        cfg.alpha_c = P(6, 0);
    }
    if (PDIM(7) > 0) {
        cfg.u_nom = P(7, 0);
    }
    if (PDIM(8) > 0) {
        cfg.w_nom = P(8, 0);
    }
    if (PDIM(9) > 0) {
        cfg.T_s = P(9, 0);
    }
    if (PDIM(10) > 0) {
        cfg.i_d_max = P(10, 0);
    }
    if (PDIM(11) > 0) {
        cfg.alpha_l = P(11, 0);
    }
    gfm_control_system_init(&ctrl, &cfg);
}

static void mdlOutputs(SimStruct *S, int_T tid)
{
    UNUSED_ARG(tid);
    /* Measurements and references */
    double i_c_abc[3] = {InputSignal(2, 0), InputSignal(2, 1),
                         InputSignal(2, 2)};
    GFMMeasurements meas = {abc2complex(i_c_abc), InputSignal(3, 0)};
    gfm_control_system_compute_output(&ctrl, &meas, InputSignal(0, 0),
                                      InputSignal(1, 0));

    /* Duty ratios, delayed by the Delay block outside the subsystem */
    for (int k = 0; k < 3; k++) {
        OutputSignal(0, k) = ctrl.ref.d_abc[k];
    }

    /* Monitored signals */
    OutputSignal(1, 0) = ctrl.ref.p_g;
    OutputSignal(1, 1) = ctrl.fbk.p_g;
    OutputSignal(1, 2) = ctrl.fbk.q_g;
    OutputSignal(2, 0) = ctrl.ref.v_c;
    OutputSignal(2, 1) = cabs(ctrl.fbk.v_c);
    OutputSignal(3, 0) = creal(ctrl.ref.i_c);
    OutputSignal(3, 1) = creal(ctrl.fbk.i_c);
    OutputSignal(3, 2) = cimag(ctrl.ref.i_c);
    OutputSignal(3, 3) = cimag(ctrl.fbk.i_c);
    OutputSignal(4, 0) = ctrl.fbk.theta_c;
}

#define MDL_UPDATE
static void mdlUpdate(SimStruct *S, int_T tid)
{
    UNUSED_ARG(tid);
    gfm_control_system_update(&ctrl);
}

static void mdlTerminate(SimStruct *S)
{
    UNUSED_ARG(S);
}

#ifdef MATLAB_MEX_FILE
#include "simulink.c"
#else
#include "cg_sfun.h"
#endif
